def get_flow_size_slowdown(
    byteload_size_B, inter_byteload_interval_nanosec, rtt_s,
    flowsize_fct_s_pairs_list
):
    fct_s_list = []
    ideal_fct_s_list = []
    for flow_size_B, fct_s in flowsize_fct_s_pairs_list:
        ideal_fct_s = dale_fe_analyse_fct_slowdown.get_theoretical_fct_single_flow_s(
            flow_size_B=flow_size_B,
            byteload_size_B=byteload_size_B,
            inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
            rtt_s=rtt_s
        )
        fct_s_list.append(fct_s)
        ideal_fct_s_list.append(ideal_fct_s)
    slowdown_list = [fct_s/ideal_fct_s for fct_s, ideal_fct_s in zip(fct_s_list, ideal_fct_s_list)]
    slowdown_list.sort()
    return slowdown_list

def plot_ssird_flow_slowdown_cdf(
    experiment_family, title_addendum, experiment_date,
    byteload_size_B, inter_byteload_interval_nanosec, rtt_s,
    num_flows_list,
    incast_degree,  # is `n` in `n-to-1` incast; i.e. how many senders are sending to a single receiver
    ssird_srpt_flowsize_fct_s_pairs_list_list,
    ssird_fairshare_flowsize_fct_s_pairs_list_list,
    x_lim=None, y_lim=None
):

    print([len(list) for list in ssird_srpt_flowsize_fct_s_pairs_list_list])
    print([len(list) for list in ssird_fairshare_flowsize_fct_s_pairs_list_list])

    assert(len(set([
        len(ssird_srpt_flowsize_fct_s_pairs_list_list),
        len(ssird_fairshare_flowsize_fct_s_pairs_list_list),
        len(num_flows_list)
    ]))==1)

    num_experiments = len(num_flows_list)
    for i in range(num_experiments):
        assert(num_flows_list[i]*incast_degree == len(ssird_srpt_flowsize_fct_s_pairs_list_list[i]))

    for i in range(num_experiments):

        ssird_srpt_slowdown = get_flow_size_slowdown(
            byteload_size_B=byteload_size_B,
            inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
            rtt_s=rtt_s,
            flowsize_fct_s_pairs_list=ssird_srpt_flowsize_fct_s_pairs_list_list[i]
        )

        ssird_fairshare_slowdown = get_flow_size_slowdown(
            byteload_size_B=byteload_size_B,
            inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
            rtt_s=rtt_s,
            flowsize_fct_s_pairs_list=ssird_fairshare_flowsize_fct_s_pairs_list_list[i]
        )

        num_flows_total = num_flows_list[i]*incast_degree
        num_flows_completed_count_cumulative = np.cumsum([1]*num_flows_total).tolist()
        proportion_of_flows_completed = [x / num_flows_total for x in num_flows_completed_count_cumulative]

        plt.figure(figsize=(10, 6))
        plt.xlabel(f'Slowdown')
        plt.ylabel('Proportion of Flows Completed')
        plt.title(f'Flow Size vs Latency {num_flows_total}flo\n{experiment_family}{title_addendum}\n{experiment_date}')

        plt.plot(ssird_srpt_slowdown, proportion_of_flows_completed, label="SSIRD (SRPT)", linestyle='-', marker='^', color=SSIRD_PLOT_COLOUR, markersize=3, zorder=3)
        plt.plot(ssird_fairshare_slowdown, proportion_of_flows_completed, label="SSIRD (Fair Share)", linestyle='-', marker='s', color=XPASS_PLOT_COLOUR, markersize=2, zorder=2)

        plt.legend()

        ax = plt.gca()
        ax.grid(True, which='both')

        if (x_lim is not None):
            ax.set_xlim(x_lim)
        if (y_lim is not None):
            ax.set_ylim(y_lim)

        # ax.set_xscale('log')

        Path(PATH_TO_FLOW_LATENCY_CDF).mkdir(parents=True, exist_ok=True)
        filename = f"ssird_flow_latency_cdf_{num_flows_total}flo_{experiment_family}{title_addendum}_{experiment_date}.png"
        plt.savefig(f"{PATH_TO_FLOW_LATENCY_CDF}{filename}")
        plt.close()
        # return

def plot_ssird_flow_slowdown_cdf_single(
    graph_title,
    experiment_family, title_addendum, experiment_date,
    byteload_size_B, inter_byteload_interval_nanosec, rtt_s,
    num_flows_list_srpt,
    num_flows_list_fairshare,
    incast_degree,  # is `n` in `n-to-1` incast; i.e. how many senders are sending to a single receiver
    target_num_flows_srpt,
    target_num_flows_fairshare,
    ssird_srpt_flowsize_fct_s_pairs_list_list,
    ssird_fairshare_flowsize_fct_s_pairs_list_list,
    x_lim=None, y_lim=None
):

    print([len(list) for list in ssird_srpt_flowsize_fct_s_pairs_list_list])
    print([len(list) for list in ssird_fairshare_flowsize_fct_s_pairs_list_list])

    assert(len(ssird_srpt_flowsize_fct_s_pairs_list_list) == len(num_flows_list_srpt))
    assert(len(ssird_fairshare_flowsize_fct_s_pairs_list_list) == len(num_flows_list_fairshare))

    num_experiments_srpt = len(num_flows_list_srpt)
    for i in range(num_experiments_srpt):
        assert(num_flows_list_srpt[i]*incast_degree == len(ssird_srpt_flowsize_fct_s_pairs_list_list[i]))
    num_experiments_fairshare = len(num_flows_list_fairshare)
    for i in range(num_experiments_fairshare):
        assert(num_flows_list_fairshare[i]*incast_degree == len(ssird_fairshare_flowsize_fct_s_pairs_list_list[i]))

    ssird_srpt_flowsize_fct_s_pairs_list = None
    num_flows_srpt = None
    for i in range(num_experiments_srpt):
        num_flows = num_flows_list_srpt[i]
        if (num_flows == target_num_flows_srpt):
            ssird_srpt_flowsize_fct_s_pairs_list = ssird_srpt_flowsize_fct_s_pairs_list_list[i]
            num_flows_srpt = num_flows
    assert(ssird_srpt_flowsize_fct_s_pairs_list is not None)
    assert(num_flows_srpt is not None)

    ssird_fairshare_flowsize_fct_s_pairs_list = None
    num_flows_fairshare = None
    for i in range(num_experiments_fairshare):
        num_flows = num_flows_list_fairshare[i]
        if (num_flows == target_num_flows_fairshare):
            ssird_fairshare_flowsize_fct_s_pairs_list = ssird_fairshare_flowsize_fct_s_pairs_list_list[i]
            num_flows_fairshare = num_flows
    assert(ssird_fairshare_flowsize_fct_s_pairs_list is not None)
    assert(num_flows_fairshare is not None)

    ssird_srpt_slowdown = get_flow_size_slowdown(
        byteload_size_B=byteload_size_B,
        inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
        rtt_s=rtt_s,
        flowsize_fct_s_pairs_list=ssird_srpt_flowsize_fct_s_pairs_list
    )

    ssird_fairshare_slowdown = get_flow_size_slowdown(
        byteload_size_B=byteload_size_B,
        inter_byteload_interval_nanosec=inter_byteload_interval_nanosec,
        rtt_s=rtt_s,
        flowsize_fct_s_pairs_list=ssird_fairshare_flowsize_fct_s_pairs_list
    )

    num_flows_total_srpt = num_flows_srpt*incast_degree
    num_flows_completed_count_cumulative_srpt = np.cumsum([1]*num_flows_total_srpt).tolist()
    proportion_of_flows_completed_srpt = [x / num_flows_total_srpt for x in num_flows_completed_count_cumulative_srpt]

    num_flows_total_fairshare = num_flows_fairshare*incast_degree
    num_flows_completed_count_cumulative_fairshare = np.cumsum([1]*num_flows_total_fairshare).tolist()
    proportion_of_flows_completed_fairshare = [x / num_flows_total_fairshare for x in num_flows_completed_count_cumulative_fairshare]

    # plt.figure(figsize=(10, 6))
    plt.figure(figsize=(8, 4))
    plt.xlabel(f'Slowdown')
    plt.ylabel('Proportion of Flows Completed')
    # plt.title(f'Flow Size vs Slowdown {num_flows_total}flo\n{experiment_family}{title_addendum}\n{experiment_date}')
    plt.title(f'Flow Size vs Slowdown\n{graph_title}')

    plt.plot(ssird_srpt_slowdown, proportion_of_flows_completed_srpt, label="SSIRD (SRPT)", linestyle='-', marker=None, color=SSIRD_PLOT_COLOUR, linewidth=3, markersize=3, zorder=3)
    plt.plot(ssird_fairshare_slowdown, proportion_of_flows_completed_fairshare, label="SSIRD (Fair Share)", linestyle='-', marker=None, color=XPASS_PLOT_COLOUR, linewidth=3, markersize=2, zorder=2)

    plt.legend()

    ax = plt.gca()
    ax.grid(True, which='both')
    ax.legend(loc='lower right')

    if (x_lim is not None):
        ax.set_xlim(x_lim)
    if (y_lim is not None):
        ax.set_ylim(y_lim)

    # ax.set_xscale('log')

    Path(PATH_TO_FLOW_LATENCY_CDF).mkdir(parents=True, exist_ok=True)
    filename = f"ssird_flow_slowdown_cdf_single_{num_flows_total_srpt}flosrpt_{num_flows_total_fairshare}flofairshare_{experiment_family}{title_addendum}_{experiment_date}.png"
    plt.savefig(f"{PATH_TO_FLOW_LATENCY_CDF}{filename}")
    plt.close()
    # return

